import{_ as t,o,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.4.14 Update Workspace Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-14-update-workspace-profile/spec.md","filePath":"feature/agency-workspace/3-4-14-update-workspace-profile/spec.md"}'),s={name:"feature/agency-workspace/3-4-14-update-workspace-profile/spec.md"};function r(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="_3-4-14-update-workspace-profile" tabindex="-1">3.4.14 Update Workspace Profile <a class="header-anchor" href="#_3-4-14-update-workspace-profile" aria-label="Permalink to &quot;3.4.14 Update Workspace Profile&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.14</td></tr><tr><td>Feature</td><td>Update Workspace Profile</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>MANAGER (only)</td></tr><tr><td>Version</td><td>2.3 — 2026-09-23 — rewritten to the standard FR format</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when the MANAGER of a Workspace submits changes to the Workspace profile or settings.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose:</strong> Lets the Workspace MANAGER keep the Workspace&#39;s details and settings accurate with day-to-day operations.</li><li><strong>Interface:</strong> Workspace settings screen at <code>/workspaces/:id/settings</code> (<code>WorkspaceSettingsPage</code>) — the same page that displays the profile (FR 3.4.13); the edit form and logo control appear on it directly, there is no separate <code>/profile/edit</code> route.</li><li><strong>Data Processing:</strong> The system loads the Workspace, merges the supplied fields into the record and settings, and returns the updated Workspace profile.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Workspace Settings Screen, edit section (<code>WorkspaceSettingsPage</code>, <code>useWorkspaceSettings</code>):</p><ul><li>Logo block (<code>LogoUploader</code>), shown only when <code>canManage</code> is true — client-side accepts image/jpeg, image/png, image/webp and rejects files over 5 MB before calling the upload endpoint.</li><li>Form pre-filled with the current name, timezone (<code>TimezoneSelect</code>), default platforms (<code>PlatformToggle</code>), report frequency (<code>FrequencyToggle</code>), industry, company size, website, phone, and location.</li><li>A &quot;Save&quot; action; on success a confirmation toast is shown (<code>workspace.settings.saveSuccess</code>) and the form keeps the newly entered values.</li><li>Out of scope for this FR but on the same screen: a &quot;Save as Template&quot; dialog (FR 3.4.17) and a Danger Zone delete-Workspace block (FR 3.4.15).</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional:</strong> name, timezone, defaultPlatforms (list), reportFrequency (WEEKLY / MONTHLY), industry (WorkspaceIndustry enum), companySize (CompanySize enum), website, phone, location. For the logo control: the uploaded image file (validated client-side as image/jpeg, image/png, or image/webp, max 5 MB).</li><li><strong>System data:</strong> The existing Workspace record and its stored settings; the caller&#39;s role in that Workspace; the stored URL of the uploaded logo.</li><li><strong>Output:</strong> The updated Workspace profile — id, name, agencyId, slug, ownerId, settings (timezone, defaultPlatforms, reportFrequency), industry, companySize, website, phone, location, description, brandColor, logoIcon, logoUrl, tagline, foundedYear, social links, isActive, createdAt.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-25:</strong> Workspace settings and logo can only be updated by OWNER or MANAGER (enforced here as MANAGER, the only role granted on this Workspace&#39;s controller endpoint); all settings fields are optional (partial update).</li><li><strong>BR-35:</strong> <code>@RequireRoleAspect</code> re-reads the caller&#39;s role from the database at request time — it never trusts the JWT claim — and runs on the controller before the service method, so the role check on <code>updateSettings</code> / <code>uploadLogo</code> precedes even the not-found lookup. SystemRole.ADMIN bypasses the check.</li><li>The Workspace must exist → otherwise 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>Fields not supplied in the request keep their current values; the stored settings are merged rather than replaced (BR-25).</li><li>A failure while reading the uploaded logo file → 400 <code>FILE_READ_ERROR</code>.</li><li>The logo is uploaded through its own dedicated action, not through the profile settings update.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>The caller must hold the MANAGER role in that Workspace (BR-25, BR-35); otherwise 403 <code>FORBIDDEN</code>.</li><li>The Workspace must exist; otherwise 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li><code>industry</code> must be a valid WorkspaceIndustry value; <code>companySize</code> must be a valid CompanySize value. Empty required field → Display: MSG02. Exceeding max length → Display: MSG03.</li><li>An unreadable logo file → 400 <code>FILE_READ_ERROR</code>. The backend <code>updateLogo</code> itself has no explicit file-type/size check on this path; the frontend (<code>useWorkspaceSettings.handleLogoChange</code>) rejects non-image/jpeg, image/png, image/webp files and files over 5 MB before the request is sent, so the backend gap is currently masked by client-side validation, not fixed server-side.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>MANAGER opens <code>/workspaces/:id/settings</code> and edits the name, timezone, default platforms, report frequency, industry, company size, website, phone, or location.</li><li>System confirms the caller holds the MANAGER role in that Workspace (BR-25, BR-35), checked by <code>@RequireRoleAspect</code> before the service runs; otherwise the request fails with 403 <code>FORBIDDEN</code>.</li><li>System loads the Workspace; if it does not exist the request fails with 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>System applies the supplied fields and merges the new timezone / default platforms into the stored settings, keeping the previous values for fields left out (BR-25).</li><li>System returns the updated Workspace profile; the screen shows a success confirmation, toast MSG32. (The separate logo upload action, on success, shows toast MSG94.)</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>2.a1: Caller is not the MANAGER of that Workspace (BR-25, BR-35) → 403 <code>FORBIDDEN</code>, toast MSG39. 2.a2: The caller stays on the same <code>/workspaces/:id/settings</code> screen with the edit controls hidden (see FR 3.4.13&#39;s <code>canManage</code> gate).</li><li>3.a1: The Workspace does not exist → 404 <code>WORKSPACE_NOT_FOUND</code>, toast MSG38. 3.a2: The MANAGER returns to the Workspace list.</li><li>3.b1: Logo upload file cannot be read → 400 <code>FILE_READ_ERROR</code>. 3.b2: The user retries with another file.</li><li>The timezone is changed while Tasks or Livestreams are already scheduled for the old timezone → the screen warns about the impact before saving; existing schedules are not moved automatically.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The Workspace record and its settings carry the new values; fields not supplied are unchanged.</li><li>When a logo was uploaded, the Workspace holds the new logo location.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Automatically rescheduling existing Tasks when the timezone changes.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',27)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
